-- GP-5E.1A tenant-owned Commercial Structure authority. Existing text is adopted exactly, not classified.
CREATE TABLE commercial_structure_heads(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),client_id UUID NOT NULL REFERENCES clients(id) ON DELETE CASCADE,name TEXT NOT NULL CHECK(char_length(btrim(name)) BETWEEN 1 AND 120),display_order INTEGER NOT NULL DEFAULT 0 CHECK(display_order>=0),is_active BOOLEAN NOT NULL DEFAULT TRUE,version INTEGER NOT NULL DEFAULT 1 CHECK(version>0),origin TEXT NOT NULL DEFAULT 'tenant',created_by_user_id UUID REFERENCES buildlite_users(id) ON DELETE RESTRICT,created_by_membership_id UUID REFERENCES client_user_memberships(id) ON DELETE RESTRICT,created_by_provider_user_id TEXT,created_by_display_name TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(client_id,id));
CREATE UNIQUE INDEX uq_commercial_structure_heads_name ON commercial_structure_heads(client_id,lower(btrim(name)));
CREATE TABLE commercial_structure_families(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),client_id UUID NOT NULL REFERENCES clients(id) ON DELETE CASCADE,head_id UUID NOT NULL,name TEXT NOT NULL CHECK(char_length(btrim(name)) BETWEEN 1 AND 120),display_order INTEGER NOT NULL DEFAULT 0 CHECK(display_order>=0),is_active BOOLEAN NOT NULL DEFAULT TRUE,version INTEGER NOT NULL DEFAULT 1 CHECK(version>0),origin TEXT NOT NULL DEFAULT 'tenant',created_by_user_id UUID REFERENCES buildlite_users(id) ON DELETE RESTRICT,created_by_membership_id UUID REFERENCES client_user_memberships(id) ON DELETE RESTRICT,created_by_provider_user_id TEXT,created_by_display_name TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(client_id,id),FOREIGN KEY(client_id,head_id) REFERENCES commercial_structure_heads(client_id,id) ON DELETE RESTRICT);
CREATE UNIQUE INDEX uq_commercial_structure_families_name ON commercial_structure_families(client_id,head_id,lower(btrim(name)));
CREATE TABLE commercial_structure_reporting_groups(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),client_id UUID NOT NULL REFERENCES clients(id) ON DELETE CASCADE,head_id UUID NOT NULL,family_id UUID,name TEXT NOT NULL CHECK(char_length(btrim(name)) BETWEEN 1 AND 120),display_order INTEGER NOT NULL DEFAULT 0 CHECK(display_order>=0),is_active BOOLEAN NOT NULL DEFAULT TRUE,version INTEGER NOT NULL DEFAULT 1 CHECK(version>0),origin TEXT NOT NULL DEFAULT 'tenant',created_by_user_id UUID REFERENCES buildlite_users(id) ON DELETE RESTRICT,created_by_membership_id UUID REFERENCES client_user_memberships(id) ON DELETE RESTRICT,created_by_provider_user_id TEXT,created_by_display_name TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(client_id,id),FOREIGN KEY(client_id,head_id) REFERENCES commercial_structure_heads(client_id,id) ON DELETE RESTRICT,FOREIGN KEY(client_id,family_id) REFERENCES commercial_structure_families(client_id,id) ON DELETE RESTRICT);
CREATE UNIQUE INDEX uq_commercial_structure_groups_family ON commercial_structure_reporting_groups(client_id,head_id,family_id,lower(btrim(name))) WHERE family_id IS NOT NULL;
CREATE UNIQUE INDEX uq_commercial_structure_groups_head ON commercial_structure_reporting_groups(client_id,head_id,lower(btrim(name))) WHERE family_id IS NULL;
CREATE FUNCTION validate_reporting_group_parentage() RETURNS trigger AS $$ DECLARE fh UUID; BEGIN IF NEW.family_id IS NOT NULL THEN SELECT head_id INTO fh FROM commercial_structure_families WHERE client_id=NEW.client_id AND id=NEW.family_id;IF fh IS DISTINCT FROM NEW.head_id THEN RAISE EXCEPTION 'Reporting Group Family does not belong to Commercial Head';END IF;END IF;RETURN NEW;END $$ LANGUAGE plpgsql;
CREATE TRIGGER trg_reporting_group_parentage BEFORE INSERT OR UPDATE OF client_id,head_id,family_id ON commercial_structure_reporting_groups FOR EACH ROW EXECUTE FUNCTION validate_reporting_group_parentage();
ALTER TABLE cost_codes ADD COLUMN commercial_head_id UUID,ADD COLUMN commercial_family_id UUID,ADD COLUMN reporting_group_id UUID;
ALTER TABLE cost_codes ADD CONSTRAINT fk_cost_codes_structure_head FOREIGN KEY(client_id,commercial_head_id) REFERENCES commercial_structure_heads(client_id,id) ON DELETE RESTRICT,ADD CONSTRAINT fk_cost_codes_structure_family FOREIGN KEY(client_id,commercial_family_id) REFERENCES commercial_structure_families(client_id,id) ON DELETE RESTRICT,ADD CONSTRAINT fk_cost_codes_structure_group FOREIGN KEY(client_id,reporting_group_id) REFERENCES commercial_structure_reporting_groups(client_id,id) ON DELETE RESTRICT;
CREATE TABLE commercial_structure_audit(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),client_id UUID NOT NULL REFERENCES clients(id) ON DELETE RESTRICT,entity_type TEXT NOT NULL CHECK(entity_type IN('head','family','reporting_group')),entity_id UUID NOT NULL,operation TEXT NOT NULL CHECK(operation IN('adopt_existing','create','update','archive','restore')),before_document JSONB,after_document JSONB,resulting_version INTEGER NOT NULL CHECK(resulting_version>0),actor_user_id UUID REFERENCES buildlite_users(id) ON DELETE RESTRICT,actor_membership_id UUID REFERENCES client_user_memberships(id) ON DELETE RESTRICT,actor_provider_user_id TEXT,actor_display_name TEXT,actor_role_key TEXT,actor_permission_key TEXT,occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE FUNCTION protect_commercial_structure_audit() RETURNS trigger AS $$ BEGIN RAISE EXCEPTION 'commercial structure audit is append-only'; END $$ LANGUAGE plpgsql;
CREATE TRIGGER trg_commercial_structure_audit_immutable BEFORE UPDATE OR DELETE ON commercial_structure_audit FOR EACH ROW EXECUTE FUNCTION protect_commercial_structure_audit();
CREATE TABLE commercial_structure_adoption_issues(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),client_id UUID NOT NULL REFERENCES clients(id) ON DELETE CASCADE,cost_code_id UUID NOT NULL REFERENCES cost_codes(id) ON DELETE CASCADE,reason TEXT NOT NULL,evidence JSONB NOT NULL,detected_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(client_id,cost_code_id,reason));
CREATE FUNCTION validate_cost_code_structure_parentage() RETURNS trigger AS $$ DECLARE fh UUID;gh UUID;gf UUID; BEGIN IF NEW.commercial_family_id IS NOT NULL THEN SELECT head_id INTO fh FROM commercial_structure_families WHERE client_id=NEW.client_id AND id=NEW.commercial_family_id;IF NEW.commercial_head_id IS NULL OR fh IS DISTINCT FROM NEW.commercial_head_id THEN RAISE EXCEPTION 'Commercial Family does not belong to Commercial Head';END IF;END IF;IF NEW.reporting_group_id IS NOT NULL THEN SELECT head_id,family_id INTO gh,gf FROM commercial_structure_reporting_groups WHERE client_id=NEW.client_id AND id=NEW.reporting_group_id;IF NEW.commercial_head_id IS NULL OR gh IS DISTINCT FROM NEW.commercial_head_id OR gf IS DISTINCT FROM NEW.commercial_family_id THEN RAISE EXCEPTION 'Reporting Group does not belong to hierarchy path';END IF;END IF;RETURN NEW;END $$ LANGUAGE plpgsql;
CREATE TRIGGER trg_cost_codes_structure_parentage BEFORE INSERT OR UPDATE OF client_id,commercial_head_id,commercial_family_id,reporting_group_id ON cost_codes FOR EACH ROW EXECUTE FUNCTION validate_cost_code_structure_parentage();
INSERT INTO commercial_structure_adoption_issues(client_id,cost_code_id,reason,evidence) SELECT client_id,id,'missing_commercial_head',jsonb_build_object('commercialHead',commercial_head,'commercialFamily',commercial_family,'reportingGroup',reporting_group) FROM cost_codes WHERE NULLIF(btrim(commercial_head),'') IS NULL AND(NULLIF(btrim(commercial_family),'') IS NOT NULL OR NULLIF(btrim(reporting_group),'') IS NOT NULL);
INSERT INTO commercial_structure_heads(client_id,name,display_order,origin) SELECT client_id,min(btrim(commercial_head)),row_number()OVER(PARTITION BY client_id ORDER BY lower(btrim(commercial_head)))-1,'existing_cost_code' FROM cost_codes WHERE NULLIF(btrim(commercial_head),'') IS NOT NULL GROUP BY client_id,lower(btrim(commercial_head));
INSERT INTO commercial_structure_families(client_id,head_id,name,display_order,origin) SELECT c.client_id,h.id,min(btrim(c.commercial_family)),row_number()OVER(PARTITION BY c.client_id,h.id ORDER BY lower(btrim(c.commercial_family)))-1,'existing_cost_code' FROM cost_codes c JOIN commercial_structure_heads h ON h.client_id=c.client_id AND lower(btrim(h.name))=lower(btrim(c.commercial_head)) WHERE NULLIF(btrim(c.commercial_family),'') IS NOT NULL GROUP BY c.client_id,h.id,lower(btrim(c.commercial_family));
INSERT INTO commercial_structure_reporting_groups(client_id,head_id,family_id,name,display_order,origin) SELECT c.client_id,h.id,f.id,min(btrim(c.reporting_group)),row_number()OVER(PARTITION BY c.client_id,h.id,f.id ORDER BY lower(btrim(c.reporting_group)))-1,'existing_cost_code' FROM cost_codes c JOIN commercial_structure_heads h ON h.client_id=c.client_id AND lower(btrim(h.name))=lower(btrim(c.commercial_head)) LEFT JOIN commercial_structure_families f ON f.client_id=c.client_id AND f.head_id=h.id AND lower(btrim(f.name))=lower(btrim(c.commercial_family)) WHERE NULLIF(btrim(c.reporting_group),'') IS NOT NULL AND(NULLIF(btrim(c.commercial_family),'') IS NULL OR f.id IS NOT NULL) GROUP BY c.client_id,h.id,f.id,lower(btrim(c.reporting_group));
UPDATE cost_codes c SET commercial_head_id=h.id FROM commercial_structure_heads h WHERE c.client_id=h.client_id AND lower(btrim(c.commercial_head))=lower(btrim(h.name));
UPDATE cost_codes c SET commercial_family_id=f.id FROM commercial_structure_families f WHERE c.client_id=f.client_id AND c.commercial_head_id=f.head_id AND lower(btrim(c.commercial_family))=lower(btrim(f.name));
UPDATE cost_codes c SET reporting_group_id=g.id FROM commercial_structure_reporting_groups g WHERE c.client_id=g.client_id AND c.commercial_head_id=g.head_id AND c.commercial_family_id IS NOT DISTINCT FROM g.family_id AND lower(btrim(c.reporting_group))=lower(btrim(g.name));
INSERT INTO commercial_structure_audit(client_id,entity_type,entity_id,operation,after_document,resulting_version) SELECT client_id,'head',id,'adopt_existing',to_jsonb(commercial_structure_heads),version FROM commercial_structure_heads WHERE origin='existing_cost_code';
INSERT INTO commercial_structure_audit(client_id,entity_type,entity_id,operation,after_document,resulting_version) SELECT client_id,'family',id,'adopt_existing',to_jsonb(commercial_structure_families),version FROM commercial_structure_families WHERE origin='existing_cost_code';
INSERT INTO commercial_structure_audit(client_id,entity_type,entity_id,operation,after_document,resulting_version) SELECT client_id,'reporting_group',id,'adopt_existing',to_jsonb(commercial_structure_reporting_groups),version FROM commercial_structure_reporting_groups WHERE origin='existing_cost_code';
INSERT INTO permissions(key,description)VALUES('commercial_structure.manage','Manage tenant Commercial Structure authority')ON CONFLICT(key)DO UPDATE SET description=EXCLUDED.description;
INSERT INTO role_permissions(role_id,permission_key)SELECT id,'commercial_structure.manage' FROM roles WHERE key='admin' ON CONFLICT DO NOTHING;
